public class PackedMediaTest{public static void main(String[] args)throws Exception{BufferedReader list=new BufferedReader(new FileReader(args[0]));int clips=0;long start=System.nanoTime();String line;while((line=list.readLine())!=null){String[] fields=line.split(",");InputStream input=PackedResources.open("/"+fields[0]);Player player=Manager.createPlayer(input,"audio/x-wav");player.realize();player.prefetch();player.start();Manager.FakePlayer fake=(Manager.FakePlayer)player;int expected=Integer.parseInt(fields[1])*2+44;if(fake.data.length!=expected)throw new Exception("Duration "+line);player.stop();player.close();input.close();Manager.players.clear();clips++;}System.out.println("MMAPI spy valid PCM11025/16: clips="+clips+" ms="+(System.nanoTime()-start)/1000000);}}
